/**
 * Embedded official Harel travel-medical proposal PDF + Heebo font
 * so Supabase Edge always has them (binary sidecars often omitted from deploys).
 */
export const TRAVEL_PROPOSAL_PDF_BASE64 = "";
export const HEEBO_FONT_BASE64 = "";

export function decodeBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
